record.field:
# Read auth parameter keys from remote.connection_params JSON
remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}
username = (cfg.get('username') or '').strip()
password = (cfg.get('password') or '').strip()
if not username or not password:
    raise Exception("Missing cesens credentials: set username/password in connection_params.")
url = (base_url or '').rstrip('/') + '/api/usuarios/login'
resp = request_retry('POST', url, json={'nombre': username, 'clave': password})
if resp.status_code >= 400:
    raise Exception("Login failed: %s %s" % (resp.status_code, resp.text))
j = resp.json() or {}
token = j.get('auth') or ''
if not token:
    raise Exception("Login OK but no 'access' token in response.")
bag['token'] = token

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today_str = fields.Date.today()
condition = [
    ('remotecontrol_params','!=',False),
    ('device_id.remotecontrol_id', '=', Remote.id)
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
sensors = Sensor.search(condition)
# Optimize: build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]
# Now iterate sensors using the map
plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}
    location_id = sensor_cfg.get('location_id') or device_cfg.get('location_id')
    sensor_id_param = sensor_cfg.get('sensor_id')
    start_cfg = sensor_cfg.get('start_date') or device_cfg.get('start_date')
    if not (location_id and sensor_id_param):
        continue
    # Retrieve last_reading from map (no query per sensor)
    last_reading_time = last_readings_map.get(sensor.id)
    if last_reading_time:
        try:
            initial_date = fields.Date.to_string(
                fields.Datetime.from_string(last_reading_time) +
                timedelta(days=1))
        except Exception:
            initial_date = str(last_reading_time)[:10]
    elif start_cfg:
        initial_date = start_cfg[:10]
    else:
        year_str = today_str[:4]
        initial_date = '%s-01-01' % year_str
    if isinstance(initial_date, unicode):
        initial_date = initial_date.encode('utf-8')
    plan.append({
        'sensor_id': sensor.id,
        'sensor_id_param': sensor_id_param,
        'device_id': device.id,
        'location_id': location_id,
        'initial_date': initial_date
    })
bag['sensors_plan'] = plan

Remote=self.remote_id
token=bag.get("token")
if not token:
    raise Exception(u"Missing Cesens token in bag")

base_url=(bag.get(u'base_url') or Remote.base_url or u'').rstrip(u'/')+u'/api'
headers={u'Authentication':u'Token %s'%token,u'Accept':u'application/json'}

resp_ubi=request_retry(u'GET',base_url+u'/ubicaciones/cliente',headers=headers,timeout=timeout)
if resp_ubi.status_code>=400:
    raise Exception(u"Error fetching devices: %s %s"%(resp_ubi.status_code,resp_ubi.text))
ubicaciones=resp_ubi.json() or []

resp_met=request_retry(u'GET',base_url+u'/metricas',headers=headers,timeout=timeout)
if resp_met.status_code>=400:
    raise Exception(u"Error fetching metrics: %s %s"%(resp_met.status_code,resp_met.text))
metricas=resp_met.json() or []

devices_list=[]
total_sensors=0
for u in ubicaciones:
    device_entry={u'id':u.get(u'id'),u'name':u.get(u'nombre'),u'sensors':[]}
    nodo=u.get(u'nodo') or {}
    conectores=nodo.get(u'conectores') or []
    for c in conectores:
        sensor=c.get(u'sensor') or {}
        metricas_s=sensor.get(u'metricas') or []
        metric_id=metricas_s[0] if isinstance(metricas_s,list) and metricas_s else None
        if metric_id is None:
            continue
        sensor_name=sensor.get(u'referencia') or sensor.get(u'nombre') or sensor.get(u'name') or u'Unnamed'
        sensor_entry={u'id':metric_id,u'name':sensor_name}
        device_entry[u'sensors'].append(sensor_entry)
        total_sensors+=1
    devices_list.append(device_entry)

metrics_info=[]
for m in metricas:
    if isinstance(m,dict):
        metrics_info.append({u'id':m.get(u'id'),u'name':m.get(u'nombre') or m.get(u'name') or u'Unnamed'})
    else:
        metrics_info.append({u'id':m,u'name':unicode(m)})

data={
    u'devices':devices_list,
    u'metrics_info':metrics_info,
    u'summary':{
        u'total_devices':len(devices_list),
        u'total_sensors':total_sensors,
        u'total_metrics':len(metrics_info),
        u'executed_at':fields.Datetime.now()
    }
}

json_str=json.dumps(data,ensure_ascii=False,indent=2)
encoded=base64.b64encode(json_str.encode(u'utf-8'))
fname=u'cesens_devices_metrics_%s.json'%fields.Datetime.now().replace(u':',u'').replace(u'-',u'').replace(u' ',u'_')

att=env[u'ir.attachment'].create({
    u'name':fname,
    u'datas_fname':fname,
    u'datas':encoded,
    u'mimetype':u'application/json',
    u'res_model':u'remotecontrol',
    u'res_id':Remote.id
})
Remote.message_post(
    body=u'[Cesens] Devices=%s Sensors=%s Metrics=%s'%(len(devices_list),total_sensors,len(metrics_info)),
    attachment_ids=[att.id]
)
bag.clear()
bag[u'total_devices']=len(devices_list)
bag[u'total_sensors']=total_sensors
bag[u'total_metrics']=len(metrics_info)
bag[u'attachment_id']=att.id
bag[u'attachment_name']=fname
